// Every theme the app knows: those plugins add (`themes: […]`) and those imported in
// Settings → Appearance (kept in this browser). Their CSS is generated by the engine
// and injected once as a <style> element; the current theme's CSS and font are also
// cached so index.html can apply them before the first paint.
import type { Plugin } from '../plugins/sdk';
import { themeCss } from './engine';
import type { ThemeDefinition } from './types';

export interface ThemeEntry {
  theme: ThemeDefinition;
  /** The plugin that adds it, or null for one imported into this browser. */
  plugin: { id: string; name: string } | null;
}

const IMPORTED_KEY = 'bt-imported-themes';
let fromPlugins: ThemeEntry[] = [];
let imported: ThemeDefinition[] = readImported();
// (snapshot is filled by inject())
let snapshot: ThemeEntry[] = [];
const listeners = new Set<() => void>();

function readImported(): ThemeDefinition[] {
  try {
    const list = JSON.parse(localStorage.getItem(IMPORTED_KEY) || '[]');
    return Array.isArray(list) ? list.filter(isTheme) : [];
  } catch {
    return [];
  }
}

/** A usable theme: an id, a name and at least one mode with the three required colours. */
export function isTheme(t: unknown): t is ThemeDefinition {
  const x = t as ThemeDefinition;
  const ok = (c: unknown) => {
    const m = c as Record<string, unknown> | undefined;
    return !!m && typeof m.background === 'string' && typeof m.foreground === 'string' && typeof m.primary === 'string';
  };
  return !!x && typeof x.id === 'string' && /^[a-z0-9-]+$/.test(x.id) && typeof x.name === 'string' && (ok(x.light) || ok(x.dark)) && (!x.light || ok(x.light)) && (!x.dark || ok(x.dark));
}

/** Called once at start-up with every installed plugin. */
export function registerThemePlugins(plugins: Plugin[]) {
  fromPlugins = plugins.flatMap((p) => (p.themes ?? []).map((theme) => ({ theme, plugin: { id: p.id, name: p.name } })));
  inject();
}

/** Every theme, plugins' first. The same array until the list changes (safe for React). */
export const allThemes = (): ThemeEntry[] => snapshot;

function rebuild() {
  const seen = new Set<string>();
  snapshot = [...fromPlugins, ...imported.map((theme) => ({ theme, plugin: null }))].filter((e) => !seen.has(e.theme.id) && !!seen.add(e.theme.id));
}

export const findTheme = (id: string) => allThemes().find((e) => e.theme.id === id)?.theme;

export function importTheme(theme: ThemeDefinition) {
  imported = [...imported.filter((t) => t.id !== theme.id), theme];
  saveImported();
}

export function removeImportedTheme(id: string) {
  imported = imported.filter((t) => t.id !== id);
  saveImported();
}

function saveImported() {
  try {
    localStorage.setItem(IMPORTED_KEY, JSON.stringify(imported));
  } catch {
    /* private window: kept for this visit only */
  }
  inject();
  listeners.forEach((l) => l());
}

export function subscribeThemes(l: () => void) {
  listeners.add(l);
  return () => listeners.delete(l);
}

function inject() {
  rebuild();
  if (typeof document === 'undefined') return;
  let el = document.getElementById('bt-themes') as HTMLStyleElement | null;
  if (!el) {
    el = document.createElement('style');
    el.id = 'bt-themes';
    document.head.append(el);
  }
  el.textContent = allThemes().map((e) => themeCss(e.theme)).join('\n');
}
